+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks. */
+export interface PlanResult {
+  /** Every task id in execution order. */
+  order: string[];
+  /** Tasks that can run at the earliest in each round. */
+  stages: string[][];
+}
+
+// Re-export error classes for public entry via planner module
+// (also exported from errors.ts, but SPEC requires they live in planner.ts and be re-exported from index)
+export { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+
+/**
+ * Plans execution order and stages for tasks.
+ *
+ * Implements SPEC \u00a72 R1-R4: priority-aware topological sort, stage calculation,
+ * and checked error order duplicate \u2192 unknown dependency \u2192 cycle.
+ *
+ * @param tasks - Tasks in the shape `parseTasks` returns.
+ * @returns order and stages per SPEC.
+ * @throws DuplicateTaskError when duplicate ids exist.
+ * @throws UnknownDependencyError when a dependency is missing.
+ * @throws CycleError when a dependency cycle exists.
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3.1 duplicate ids
+  const count = new Map<string, number>();
+  const firstPos = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const id = t.id;
+    count.set(id, (count.get(id) ?? 0) + 1);
+    if (!firstPos.has(id)) firstPos.set(id, i);
+  }
+  const dups: string[] = [];
+  for (const [id, c] of count) {
+    if (c > 1) dups.push(id);
+  }
+  if (dups.length > 0) {
+    dups.sort((a, b) => (firstPos.get(a)! - firstPos.get(b)!));
+    throw new DuplicateTaskError(dups);
+  }
+
+  // Map id -> index
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    idToIndex.set(t.id, i);
+  }
+
+  // R3.2 unknown dependency
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const deps = t.dependsOn;
+    for (let j = 0; j < deps.length; j++) {
+      const dep = deps[j]!;
+      if (!idToIndex.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build graph with deduped dependencies
+  const forwardAdj: number[][] = Array.from({ length: n }, () => []);
+  const reverseAdj: number[][] = Array.from({ length: n }, () => []);
+  const indegree = new Array<number>(n).fill(0);
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const deps = t.dependsOn;
+    const seen = new Set<string>();
+    for (const dep of deps) {
+      if (seen.has(dep)) continue;
+      seen.add(dep);
+      const depIdx = idToIndex.get(dep)!;
+      forwardAdj[i]!.push(depIdx);
+      reverseAdj[depIdx]!.push(i);
+      indegree[i]!++;
+    }
+  }
+
+  // Kahn with priority
+  const levels = new Array<number>(n).fill(0);
+  const best = new Array<number>(n).fill(-1);
+
+  // heap for ready nodes: max-heap by priority then input order
+  const heap: number[] = [];
+  function better(a: number, b: number): boolean {
+    const ta = tasks[a]!;
+    const tb = tasks[b]!;
+    const pa = ta.priority;
+    const pb = tb.priority;
+    if (pa !== pb) return pa > pb;
+    return a < b;
+  }
+  function heapPush(v: number): void {
+    heap.push(v);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      const hp = heap[p]!;
+      const hi = heap[i]!;
+      if (better(hp, hi)) break;
+      const tmp = heap[p]!;
+      heap[p] = heap[i]!;
+      heap[i] = tmp;
+      i = p;
+    }
+  }
+  function heapPop(): number {
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        const l = i * 2 + 1;
+        const r = l + 1;
+        let bestIdx = i;
+        if (l < heap.length) {
+          const hl = heap[l]!;
+          const hb = heap[bestIdx]!;
+          if (better(hl, hb)) bestIdx = l;
+        }
+        if (r < heap.length) {
+          const hr = heap[r]!;
+          const hb2 = heap[bestIdx]!;
+          if (better(hr, hb2)) bestIdx = r;
+        }
+        if (bestIdx === i) break;
+        const tmp = heap[i]!;
+        heap[i] = heap[bestIdx]!;
+        heap[bestIdx] = tmp;
+        i = bestIdx;
+      }
+    }
+    return top;
+  }
+
+  for (let i = 0; i < n; i++) {
+    if (indegree[i]! === 0) {
+      levels[i] = 0;
+      heapPush(i);
+    }
+  }
+
+  const orderIdx: number[] = [];
+  while (heap.length > 0) {
+    const u = heapPop();
+    orderIdx.push(u);
+    const lu = levels[u]!;
+    const rev = reverseAdj[u]!;
+    for (const v of rev) {
+      if (lu > best[v]!) best[v] = lu;
+      indegree[v]!--;
+      if (indegree[v]! === 0) {
+        levels[v] = best[v]! + 1;
+        heapPush(v);
+      }
+    }
+  }
+
+  if (orderIdx.length !== n) {
+    const color = new Uint8Array(n); // 0 unvisited,1 visiting,2 done
+    const posMap = new Map<number, number>();
+    const path: number[] = [];
+    let cycleIds: string[] | null = null;
+
+    for (let start = 0; start < n && cycleIds === null; start++) {
+      if (color[start]! !== 0) continue;
+      type Frame = { v: number; next: number };
+      const stack: Frame[] = [{ v: start, next: 0 }];
+      color[start] = 1;
+      path.push(start);
+      posMap.set(start, path.length - 1);
+      while (stack.length > 0 && cycleIds === null) {
+        const frame = stack[stack.length - 1]!;
+        const v = frame.v;
+        const adj = forwardAdj[v]!;
+        if (frame.next < adj.length) {
+          const w = adj[frame.next++]!;
+          if (color[w]! === 0) {
+            color[w] = 1;
+            path.push(w);
+            posMap.set(w, path.length - 1);
+            stack.push({ v: w, next: 0 });
+          } else if (color[w]! === 1) {
+            const wPos = posMap.get(w)!;
+            const slice = path.slice(wPos);
+            const ids = slice.map((idx) => tasks[idx]!.id);
+            ids.push(tasks[w]!.id);
+            cycleIds = ids;
+            break;
+          } else {
+            // visited done -> ignore
+          }
+        } else {
+          color[v] = 2;
+          posMap.delete(v);
+          path.pop();
+          stack.pop();
+        }
+      }
+    }
+    if (cycleIds === null) {
+      cycleIds = [];
+    }
+    throw new CycleError(cycleIds);
+  }
+
+  const order = orderIdx.map((i) => tasks[i]!.id);
+
+  // Build stages
+  let maxLevel = 0;
+  if (n > 0) {
+    maxLevel = levels[0]!;
+    for (let i = 1; i < n; i++) if (levels[i]! > maxLevel) maxLevel = levels[i]!;
+  }
+  const stagesByLevel: number[][] = Array.from({ length: maxLevel + 1 }, () => []);
+  for (let i = 0; i < n; i++) {
+    const lvl = levels[i]!;
+    stagesByLevel[lvl]!.push(i);
+  }
+  const stages: string[][] = stagesByLevel.map((arr) => {
+    arr.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    return arr.map((idx) => tasks[idx]!.id);
+  });
+
+  return { order, stages };
+}
